import{_ as e,o,c as i,ai as a}from"./chunks/framework.jD4ETUAz.js";const d=JSON.parse('{"title":"性能与稳定性","description":"cninfo-mcp 如何应对巨潮资讯网的限流：全局限速、403 冷却重试、证券目录与文档缓存，以及用 complete 字段标明结果是否完整。","frontmatter":{"title":"性能与稳定性","description":"cninfo-mcp 如何应对巨潮资讯网的限流：全局限速、403 冷却重试、证券目录与文档缓存，以及用 complete 字段标明结果是否完整。","lastUpdated":"2026-11-15T21:29:49.000Z","upstream":"docs/reliability.md","head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/reference/reliability"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"性能与稳定性 | cninfo-mcp"}],["meta",{"property":"og:description","content":"cninfo-mcp 如何应对巨潮资讯网的限流：全局限速、403 冷却重试、证券目录与文档缓存，以及用 complete 字段标明结果是否完整。"}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/reference/reliability"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"性能与稳定性 | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"cninfo-mcp 如何应对巨潮资讯网的限流：全局限速、403 冷却重试、证券目录与文档缓存，以及用 complete 字段标明结果是否完整。"}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"参考\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/reference/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"性能与稳定性\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/reference/reliability\\"}]}]}"]]},"headers":[],"relativePath":"reference/reliability.md","filePath":"reference/reliability.md","lastUpdated":1794778189000}'),n={name:"reference/reliability.md"};function r(l,t,c,p,s,m){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="性能与稳定性" tabindex="-1">性能与稳定性 <a class="header-anchor" href="#性能与稳定性" aria-label="Permalink to &quot;性能与稳定性&quot;">​</a></h1><h2 id="查询" tabindex="-1">查询 <a class="header-anchor" href="#查询" aria-label="Permalink to &quot;查询&quot;">​</a></h2><ul><li><strong>按 orgId 精确查询</strong>：先用本地缓存的证券目录把代码解析成巨潮的 orgId，一条请求链即可查到一家公司在沪、深、北任一市场的公告，不必逐个交易所扫描后再过滤。同一发行人的多个代码（A+B 股、北交所新旧代码）会一并查询。</li><li><strong>并发翻页</strong>：上游每页最多 30 条。第一页返回总数后，其余分页并发抓取。</li></ul><h2 id="限速与重试" tabindex="-1">限速与重试 <a class="header-anchor" href="#限速与重试" aria-label="Permalink to &quot;限速与重试&quot;">​</a></h2><ul><li><strong>全局限速</strong>：所有上游请求共用一个并发上限（默认 4）和最小发起间隔，多个工具调用同时进行时也不会叠加。</li><li><strong>限流冷却</strong>：巨潮用 403 表达限流。遇到 403 / 429 时全局暂停一段时间再重试，而不是继续撞限流。</li><li><strong>自动重试</strong>：超时、网络错误、5xx、空响应、数据接口的内部失败（HTTP 200 但 <code>resultMsg=fail</code>）按指数退避加抖动重试；404 等确定性错误立即返回。</li></ul><p>并发上限不建议调高：短时间内大量请求会让巨潮返回 403 并暂时封禁 IP。</p><h2 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h2><ul><li><strong>证券目录</strong>：内存和磁盘各一份，12 小时更新一次；上游不可用时退回磁盘上的旧副本。</li><li><strong>查询结果</strong>：短时缓存，并合并同时发起的相同请求。不完整的结果不进缓存。</li><li><strong>文档</strong>：读过的文档及其逐页文本落盘缓存，再次读取或下载不需要重新抓取和解析。缓存超过上限时淘汰最久未使用的文件。</li></ul><h2 id="结果完整性与故障隔离" tabindex="-1">结果完整性与故障隔离 <a class="header-anchor" href="#结果完整性与故障隔离" aria-label="Permalink to &quot;结果完整性与故障隔离&quot;">​</a></h2><ul><li>部分分页、部分数据集或部分文件失败时，已取得的内容照常返回，并用 <code>complete: false</code> 明确标出，不会把残缺结果当作完整结果。</li><li>单个文件下载失败、单个数据集失败、单页 PDF 解析失败都不会拖垮整次调用。</li><li>下载和缓存都是先写临时文件再原子改名；限流时返回的 HTML 错误页不会被当作 PDF 保存。</li><li>客户端退出后服务器随即结束，不留下孤儿进程。</li></ul><h2 id="监控" tabindex="-1">监控 <a class="header-anchor" href="#监控" aria-label="Permalink to &quot;监控&quot;">​</a></h2><p>仓库的定时工作流每天运行一次 <code>cninfo-mcp probe</code>，实际探测沪、深、北交所的年报查询、财务数据接口和文档读取，异常时自动开 issue。</p>',12)])])}const g=e(n,[["render",r]]);export{d as __pageData,g as default};
